async function queryAll(table,{userId=null,order=null}={}){
 let rows=[];for(let from=0;;from+=1000){let q=db.from(table).select('*').range(from,from+999);if(userId)q=q.eq('user_id',userId);if(order)q=q.order(order,{ascending:false});const {data,error}=await q;if(error)throw error;rows.push(...data);if(data.length<1000)break;}return rows;
}
