  db=window.supabase.createClient('https://lftguwmyagkehqmaxjig.supabase.co','sb_publishable_YzhfBB0z3emKU-rM8f_18A_Z0RUJUYt');
  window.GAB_SESSION?.watch(db);
  const {data,error}=await db.auth.getUser();
  if(error&&error.name!=='AuthSessionMissingError')throw error;
