 $('#half').onchange=e=>{stopAudio();audioState.half=e.target.value==='half';};$('#rhythm-select').onchange=e=>{stopAudio();audioState.id=e.target.value;rhythmView();};
 document.querySelectorAll('[data-beat]').forEach(b=>b.onclick=()=>{stopAudio();const i=Number(b.dataset.beat),hits=new Set(audioState.hits||[]);hits.has(i)?hits.delete(i):hits.add(i);audioState.hits=[...hits].sort((a,b)=>a-b);document.querySelectorAll('[data-beat]').forEach(x=>{const on=hits.has(Number(x.dataset.beat));x.classList.toggle('hit',on);x.setAttribute('aria-pressed',String(on));});$('#phrase-picture').innerHTML=rhythmPicture();$('#play-rhythm').disabled=!hits.size;$('#audio-status').textContent='Local grid edit. Not shared with students until a teacher publishes it.';});
